<?php $esc=function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};$asset=function($f){return $f?base_url().'upload/qms_report_assets/'.rawurlencode(basename($f)):'';};$val=function($k)use($settings){return $settings&&isset($settings->$k)?$settings->$k:'';};?><!doctype html><html><head><meta charset="utf-8"><?php include('includes/page-title.php');?><link href="<?=base_url()?>assets/css/bootstrap.min.css" rel="stylesheet"><link href="<?=base_url()?>assets/css/app.min.css" rel="stylesheet"><style>body{background:#f4f6fb}.card{max-width:900px;margin:25px auto}.preview{max-width:100%;max-height:180px;display:block;margin-top:10px}</style></head><body><div id="wrapper"><?php include('includes/top-bar.php');include('includes/sidebar.php');?><div class="content-page"><div class="content"><div class="container-fluid"><div class="card"><div class="card-body"><h3>QMS Report Settings</h3><p><?=$esc($sectionName)?></p><form method="post" action="<?=base_url()?>Page/qms_report_settings_save" enctype="multipart/form-data"><div class="form-group"><label>Letterhead image</label><input class="form-control-file" type="file" name="letterhead"><?php if($settings&&$settings->letterhead_file):?><img class="preview" src="<?=$esc($asset($settings->letterhead_file))?>"><?php endif;?></div><div class="form-group"><label>Footer image</label><input class="form-control-file" type="file" name="footer"><?php if($settings&&$settings->footer_file):?><img class="preview" src="<?=$esc($asset($settings->footer_file))?>"><?php endif;?></div><hr><h5>Risk Registry Signatories</h5><div class="form-row"><div class="form-group col-md-6"><label>Prepared by</label><input class="form-control" name="risk_prepared_by" value="<?=$esc($val('risk_prepared_by'))?>"></div><div class="form-group col-md-6"><label>Approved by</label><input class="form-control" name="risk_approved_by" value="<?=$esc($val('risk_approved_by'))?>"></div></div><hr><h5>Monitoring &amp; Review Signatories</h5><div class="form-row"><div class="form-group col-md-4"><label>Monitored by</label><input class="form-control" name="monitored_by" value="<?=$esc($val('monitored_by'))?>"></div><div class="form-group col-md-4"><label>Reviewed by</label><input class="form-control" name="reviewed_by" value="<?=$esc($val('reviewed_by'))?>"></div><div class="form-group col-md-4"><label>Acknowledged by</label><input class="form-control" name="acknowledged_by" value="<?=$esc($val('acknowledged_by'))?>"></div></div><button class="btn btn-primary">Save Settings</button></form></div></div></div></div><?php include('includes/footer.php');?></div></div></body></html>
